def _grt_metrics(directory: Path) -> Dict[str, object]:
    log = directory / "grt.log"
    text = log.read_text(encoding="utf-8", errors="replace")
    if "OPEN3D_GRT_DONE die={}".format(directory.name) not in text:
        raise ThreeDRouteError("GRT has no completion marker: {}".format(log))
    lengths = re.findall(r"\[INFO GRT-0018\] Total wirelength:\s*([0-9.]+)\s+um", text)
    times = re.findall(r"Global routing runtime\s*=\s*(\d+):(\d+):(\d+)", text)
    if not lengths or not times:
        raise ThreeDRouteError("GRT has no wirelength/runtime summary: {}".format(log))
    hours, minutes, seconds = map(int, times[-1])
    overflow = _grt_overflow_count(log)
    return {
        "grt_total_overflow": overflow,
        "grt_congestion_bins": _grt_congestion_count(directory, overflow),
        "grt_wire_length_um": float(lengths[-1]),
        "grt_native_runtime_seconds": hours * 3600 + minutes * 60 + seconds,
    }


def _artifact_records(directory: Path, names: Sequence[str]) -> Dict[str, object]:
    records = {}
    for name in names:
        path = directory / name
        if not path.is_file() or path.is_symlink():
            raise ThreeDRouteError("missing or symlinked routing artifact: {}".format(path))
        records[name] = {"size_bytes": path.stat().st_size, "sha256": _sha256(path)}
    return records


def _seal_grt(directory: Path, script_text: str, runtime_seconds: float) -> dict:
    payload = {
        "schema_version": 1,
        "stage": "global_route",
        "status": "success",
        "signature": hashlib.sha256(script_text.encode("utf-8")).hexdigest(),
        "artifacts": _artifact_records(directory, GRT_ARTIFACTS),
        "metrics": _grt_metrics(directory),
        "runtime_seconds": runtime_seconds,
    }
    _write_json(directory / "grt_manifest.json", payload)
    return payload


def _load_grt_manifest(directory: Path, script_text: str) -> Optional[dict]:
    path = directory / "grt_manifest.json"
    if not path.is_file():
        return None
    payload = json.loads(path.read_text(encoding="utf-8"))
    expected = hashlib.sha256(script_text.encode("utf-8")).hexdigest()
    if (payload.get("stage") != "global_route" or payload.get("status") != "success"
            or payload.get("signature") != expected):
        raise ThreeDRouteError("GRT signature mismatch; use a new output directory: {}".format(path))
    if payload.get("artifacts") != _artifact_records(directory, GRT_ARTIFACTS):
        raise ThreeDRouteError("GRT artifact hash/size mismatch: {}".format(path))
    if payload.get("metrics") != _grt_metrics(directory):
        raise ThreeDRouteError("GRT metrics mismatch: {}".format(path))
    return payload


def _routing_support_signature(paths: Sequence[Path], executable: str) -> str:
    tool = shutil.which(executable)
    if tool is None:
        raise ThreeDRouteError("OpenROAD executable is unavailable: {}".format(executable))
    files = sorted(set([Path(tool).resolve(), Path(__file__).resolve(),
                        Path(__file__).with_name("die_sdc.py"),
                        Path(__file__).with_name("sdc_handoff.py"),
                        Path(__file__).with_name("sdc_buffer_proof.py"), *paths]))
    hashes = {str(path): _sha256(path) for path in files}
    return hashlib.sha256(json.dumps(hashes, sort_keys=True).encode("utf-8")).hexdigest()


def _route_can_resume(directory: Path, die: str) -> bool:
    """Recognize a fully emitted die route before stage-level publication.

    Routing is intentionally bounded but can still take several minutes.  A
    later die or report-contract failure must not discard a completed first
    die.  The generated Tcl is compared separately before reuse so changed
    inputs or options still force a clean rerun.
    """

    required = (
        "route.tcl",
        "route.log",
        "design.odb",
        "design.def",
        "design.v",
        "design.sdc",
        "route.guide",
        "global_route.odb",
        "route_status.tsv",
        "drc.rpt",
        "antenna_post.rpt",
    )
    if not all((directory / name).is_file() for name in required):
        return False
    marker = "OPEN3D_ROUTE_DONE die={}".format(die)
    return marker in (directory / "route.log").read_text(
        encoding="utf-8", errors="replace"
    )


def _antenna_count(path: Path) -> int:
    if not path.is_file():
        raise ThreeDRouteError("missing antenna report: {}".format(path))
    text = path.read_text(encoding="utf-8", errors="replace")
    match = re.search(r"Found\s+(\d+)\s+net violations", text)
    if match:
        return int(match.group(1))
    return sum("VIOLATED" in line.top() for line in text.splitlines())


